# --- Chaos Engineering Test ---
@pytest.mark.asyncio
async def test_chaos_random_failures(provider, mock_api_clients):
    """Simulate random API failures and verify resilience."""
    import random
    random.seed(42)

    resources = [
        {"kind": "ConfigMap", "metadata": {"name": f"cm-{i}", "namespace": "ns1"}}
        for i in range(20)
    ]

    # Simulate 30% failure rate
    def flaky_create(*args, **kwargs):
        if random.random() < 0.3:
            raise Exception("Simulated chaos failure")
        return MagicMock()

    mock_api_clients["core"].create_config_map.side_effect = flaky_create

    result = await provider.apply(resources)

    assert result["success"] is False
    assert result["applied"] + result["failed"] == 20
    assert result["failed"] > 0
    assert len(result["errors"]) == result["failed"]

# --- Performance Test ---
@pytest.mark.asyncio
async def test_apply_concurrent_calls(provider, mock_api_clients):
    """Test concurrent apply() calls for race conditions."""
    mock_api_clients["core"].create_config_map.return_value = MagicMock()

    resources = [
        {"kind": "ConfigMap", "metadata": {"name": "cm1", "namespace": "ns1"}}
    ]

    # Run 10 concurrent apply calls
    tasks = [provider.apply(resources) for _ in range(10)]
    results = await asyncio.gather(*tasks)

    for result in results:
        assert result["success"] is True
        assert result["applied"] == 1

